interface GoldenCombo {
  order: string;
  future: number;
  completed: number;
  total: number;
}

const GOLDEN = JSON.parse(GOLDEN_JSON) as Record<string, GoldenCombo>;

const MODES = ['showAll', 'sortCompletedLast', 'hideCompleted'] as const;
const FUTURES = ['showAll', 'showUpcoming', 'sortToEnd', 'hideFuture'] as const;

function parseVault(vault: ReturnType<typeof generateVault>): Task[] {
  const settings = createBaseSettings({
    scanCodeFiles: true,
    detectOrgModeFiles: true,
  });
  const keywordManager = createTestKeywordManager(settings);
  const mdParser = TaskParser.create(keywordManager, null, undefined, {
    includeCalloutBlocks: true,
    includeCodeBlocks: true,
    includeCommentBlocks: true,
  });
  const codeParser = CodeCommentTaskParser.create(keywordManager);
  const orgParser = OrgModeTaskParser.create(keywordManager, null);

  const tasks: Task[] = [];
  for (const file of vault.files) {
    if (file.path.endsWith('.md')) {
      tasks.push(...mdParser.parseFile(file.content, file.path));
    } else if (file.path.endsWith('.org')) {
      tasks.push(...orgParser.parseFile(file.content, file.path));
    } else {
      tasks.push(...codeParser.parseFile(file.content, file.path));
    }
  }
  return tasks;
}

function createPlugin(
  futureTaskSorting: TodoTrackerSettings['futureTaskSorting'],
) {
  const settings = {
    ...createBaseSettings({ scanCodeFiles: true, detectOrgModeFiles: true }),
    futureTaskSorting,
  };
  return {
    settings,
    keywordManager: new KeywordManager(settings),
  } as unknown as TodoTracker;
}

function orderOf(result: Task[]): string {
  return result.map((t) => `${t.path}:${t.line}`).join('|');
}

describe('classify-once golden pins (fixture s, seed 1337, frozen FIXED_TODAY)', () => {
  let tasks: Task[];

  beforeAll(() => {
    tasks = parseVault(generateVault('s', 1337, FIXED_TODAY));
  });

  beforeEach(() => {
    jest.useFakeTimers().setSystemTime(FIXED_TODAY);
  });

  afterEach(() => {
    jest.useRealTimers();
  });

  it('captured golden is internally consistent (12 combos, full coverage)', () => {
    expect(Object.keys(GOLDEN)).toHaveLength(12);
    for (const future of FUTURES) {
      for (const mode of MODES) {
        const combo = GOLDEN[`${future}/${mode}`];
        expect(combo).toBeDefined();
        expect(combo.total).toBe(tasks.length);
        // Plan 029 invariant: shown + hidden.future + hidden.completed = total
        expect(
          combo.order.split('|').length + combo.future + combo.completed,
        ).toBe(combo.total);
      }
    }
  });

  it('default call shape reproduces the golden order and counts byte-for-byte', () => {
    for (const future of FUTURES) {
      const filter = new TaskListFilter(
        createPlugin(future),
        createPlugin(future).keywordManager,
      );
      for (const mode of MODES) {
        const combo = GOLDEN[`${future}/${mode}`];
        expect(
          `${future}/${mode} ${orderOf(filter.transformForView(tasks, mode, 'default'))}`,
        ).toBe(`${future}/${mode} ${combo.order}`);
        const hidden = filter.countHiddenByFilters(tasks, mode);
        expect(`${future}/${mode} ${hidden.future}/${hidden.completed}`).toBe(
          `${future}/${mode} ${combo.future}/${combo.completed}`,
        );
      }
    }
  });

  it('threaded (shared-map) call shape reproduces the same golden bytes', () => {
    for (const future of FUTURES) {
      const filter = new TaskListFilter(
        createPlugin(future),
        createPlugin(future).keywordManager,
      );
      for (const mode of MODES) {
        const combo = GOLDEN[`${future}/${mode}`];
        const classifications = new Map<Task, taskSort.TaskClassification>();
        const sorted = filter.transformForView(
          tasks,
          mode,
          'default',
          classifications,
        );
        expect(`${future}/${mode} ${orderOf(sorted)}`).toBe(
          `${future}/${mode} ${combo.order}`,
        );
        const hidden = filter.countHiddenByFilters(
          tasks,
          mode,
          classifications,
        );
        expect(`${future}/${mode} ${hidden.future}/${hidden.completed}`).toBe(
          `${future}/${mode} ${combo.future}/${combo.completed}`,
        );
      }
    }
  });

  it('classifyAll covers every task and equals classifyTask per task', () => {
    const now = new Date();
    const settings = createPlugin('showAll').settings;
    const warningSettings = {
      upcomingPeriod: settings.upcomingPeriod,
      defaultDeadlineWarningPeriod: settings.defaultDeadlineWarningPeriod,
      defaultScheduledWarningPeriod: settings.defaultScheduledWarningPeriod,
      skipScheduledWarningPeriodIfDeadline:
        settings.skipScheduledWarningPeriodIfDeadline,
      skipDeadlinePrewarningIfScheduled:
        settings.skipDeadlinePrewarningIfScheduled,
    };
    const map = classifyAll(tasks, now, warningSettings);
    expect(map.size).toBe(tasks.length);
    for (const task of tasks) {
      expect(map.get(task)).toEqual(classifyTask(task, now, warningSettings));
    }
  });

  it('shared-map pair runs exactly one classify pass; the unthreaded pair runs two', () => {
    const settings = createPlugin('hideFuture').settings;
    const filter = new TaskListFilter(
      createPlugin('hideFuture'),
      createPlugin('hideFuture').keywordManager,
    );
    // The export spy observes filter-module calls only: sortTasksInBlocks'
    // default-path classification is a same-module call and is pinned by the
    // golden/order equality instead. What this pins is the dedup contract:
    // threaded, the hidden-count pass performs ZERO classifications (the
    // shared map covers every task); unthreaded it performs a full pass.
    const spy = jest.spyOn(taskSort, 'classifyTask');
    try {
      spy.mockClear();
      const classifications = new Map<Task, taskSort.TaskClassification>();
      filter.transformForView(tasks, 'showAll', 'default', classifications);
      expect(classifications.size).toBe(tasks.length);
      filter.countHiddenByFilters(tasks, 'showAll', classifications);
      expect(spy).toHaveBeenCalledTimes(0);

      spy.mockClear();
      filter.transformForView(tasks, 'showAll', 'default');
      filter.countHiddenByFilters(tasks, 'showAll');
      expect(spy).toHaveBeenCalledTimes(tasks.length);
    } finally {
      spy.mockRestore();
    }
  });
});
